export function attachmentPreviewFixture(url: string) {
  let path = url;
  try {
    const parsed = new URL(url);
    path = parsed.searchParams.get("path") ?? parsed.pathname;
  } catch {
    /* raw host path */
  }
  if (!path.startsWith("/attachment-preview/")) return null;
  return files[path.slice("/attachment-preview/".length)] ?? null;
}
